const PLUGIN_NEW="const HostActionV2=z.enum(['agent_api_process_sandbox_v1','agent_api_filesystem_confinement_v1','agent_api_capability_minimize_v1','leadops_language_gate_v1','mcp_candidate_schema_compare_v1','leadops_economics_inputs_foundation_v1','solo_company_selftest_v1','real_market_shadow_uat_v1','real_market_verified_economics_uat_v1']);";
