const POSITIVE_BLOCK="const REAL_MARKET_VERIFIED_ECONOMICS_UAT_HELPER='/opt/prhm-agent-selfmaint-exec/actions/real-market-verified-economics-uat-v1.js';\nconst REAL_MARKET_VERIFIED_ECONOMICS_UAT_RESULT='/var/lib/prhm-agent-selfmaint-exec/real-market-verified-economics-uat-v1/latest.json';\nfunction applyRealMarketVerifiedEconomicsUatV1(){\n  if(!fs.existsSync(REAL_MARKET_VERIFIED_ECONOMICS_UAT_HELPER))throw new Error('real_market_verified_economics_uat_helper_missing');\n  try{if(fs.existsSync(REAL_MARKET_VERIFIED_ECONOMICS_UAT_RESULT))fs.unlinkSync(REAL_MARKET_VERIFIED_ECONOMICS_UAT_RESULT)}catch{}\n  const unit='prhm-real-market-verified-economics-uat-v1-'+Date.now();\n  const args=['--wait','--unit='+unit,'--property=Type=oneshot','--property=UMask=0077','--property=NoNewPrivileges=true','--property=PrivateTmp=true','--property=ProtectSystem=full','--property=ProtectHome=read-only','--property=RestrictAddressFamilies=AF_UNIX AF_INET AF_INET6','--property=ReadWritePaths=/var/lib/prhm-agent-selfmaint-exec /run/prhm-p0-shadow-worker','--setenv=PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin','/usr/local/bin/prhm-node',REAL_MARKET_VERIFIED_ECONOMICS_UAT_HELPER];\n  cp.execFileSync('/usr/bin/systemd-run',args,{encoding:'utf8',stdio:['ignore','pipe','pipe'],timeout:240000});\n  if(!fs.existsSync(REAL_MARKET_VERIFIED_ECONOMICS_UAT_RESULT))throw new Error('real_market_verified_economics_uat_result_missing');\n  const result=readJson(REAL_MARKET_VERIFIED_ECONOMICS_UAT_RESULT);\n  if(result.ok!==true||result.action!=='real_market_verified_economics_uat_v1'||result.schema_version!=='prhm.host-action-result.v1'||result.mode!=='historical_real_market_replay'||result.decision!=='SEND_NOW'||result.reason!=='profitable'||Number(result.economic_floor)!==800000||Number(result.final_bid)!==800000||Number(result.net_profit)!==569100||result.cleanup_verified!==true||result.fact_residue!==false||result.uat_decision_residue!==false||result.resolved_economics_count!==9||result.required_economics_complete!==true||result.provenance_verified!==true||result.worker_filtered_to_opportunity!==true||result.auto_send_allowed!==false||result.outbox_write!==false||result.bid_write!==false||result.telegram_write!==false||result.business_mutation!==false||result.p0_live!==false||result.proposal_send!==false||result.bid_send!==false)throw new Error('real_market_verified_economics_uat_result_invalid');\n  return result;\n}\n";
function fail(m){throw new Error(m)}
function shaBuf(b){return crypto.createHash('sha256').update(b).digest('hex')}
function sha(f){return shaBuf(fs.readFileSync(f))}
function replaceOnce(s,a,b,l){const i=s.indexOf(a);if(i<0)fail('anchor_missing:'+l);if(s.indexOf(a,i+1)>=0)fail('anchor_not_unique:'+l);return s.slice(0,i)+b+s.slice(i+a.length)}
function exec(f,args,opt={}){const r=cp.spawnSync(f,args,{encoding:'utf8',maxBuffer:4*1024*1024,...opt});if(r.error)fail('exec_error:'+f+':'+r.error.message);if(r.status!==0)fail('exec_failed:'+f+':'+r.status+':'+String(r.stderr||'').slice(-1800));return r}
function baseline(){for(const [f,x] of Object.entries(EXPECTED)){if(!fs.existsSync(f))fail('missing:'+f);const a=sha(f);if(a!==x)fail('sha_mismatch:'+f+':'+a+':'+x)}if(fs.existsSync(FILES.helper))fail('helper_already_exists')}
function patchBase(s){return replaceOnce(s,BASE_OLD,BASE_NEW,'base_spec')}
function patchExecutor(s){s=replaceOnce(s,EXEC_SPEC_OLD,EXEC_SPEC_NEW,'executor_spec');s=replaceOnce(s,'function verifyProcessSandboxV2(){',POSITIVE_BLOCK+'function verifyProcessSandboxV2(){','executor_apply_block');s=replaceOnce(s,DISPATCH_OLD,DISPATCH_NEW,'executor_dispatch');s=replaceOnce(s,VERSION_OLD,VERSION_NEW,'executor_version');return s}
function patchPlugin(s){return replaceOnce(s,PLUGIN_OLD,PLUGIN_NEW,'plugin_enum')}
function patchPolicy(s){const p=JSON.parse(s);if(p.operations?.['host_action.real_market_verified_economics_uat_v1'])fail('policy_operation_already_present');p.operations['host_action.real_market_verified_economics_uat_v1']={level:4};if(!Array.isArray(p.typed_scopes))fail('policy_typed_scopes_missing');if(p.typed_scopes.some(x=>x&&x.action===ACTION))fail('policy_scope_already_present');p.typed_scopes.push({tool:'host_action_v2_apply',project:'control_plane',environment:'production',action:ACTION,risk:'critical',operation:'host_action.real_market_verified_economics_uat_v1',principals:[{principal_id:'mohammad',roles:['mcp-operator']}]});p.version='2026-08-15.3-verified-economics-replay-v1';return JSON.stringify(p,null,2)+String.fromCharCode(10)}
function patchV4Helper(s,newPluginSha){return replaceOnce(s,EXPECTED[FILES.plugin],newPluginSha,'v4_plugin_sha')}
function syntax(name,content,esm=false){const ext=esm?'.mjs':'.js',tmp='/tmp/prhm-v8-'+name+'-'+process.pid+ext;try{fs.writeFileSync(tmp,content,{mode:0o600});exec('/usr/local/bin/prhm-node',['--check',tmp])}finally{try{fs.unlinkSync(tmp)}catch{}}}
function unixHealth(sock,version){for(let i=0;i<50;i++){const r=cp.spawnSync('/usr/bin/curl',['-fsS','--max-time','2','--unix-socket',sock,'http://localhost/health'],{encoding:'utf8'});if(r.status===0){try{const x=JSON.parse(r.stdout);if(x.ok===true&&(!version||x.version===version))return x}catch{}}Atomics.wait(new Int32Array(new SharedArrayBuffer(4)),0,0,200)}fail('unix_health_not_ready:'+sock)}
function loopHealth(port){for(let i=0;i<50;i++){const r=cp.spawnSync('/usr/bin/curl',['-fsS','--max-time','2','http://127.0.0.1:'+port+'/health'],{encoding:'utf8'});if(r.status===0){try{const x=JSON.parse(r.stdout);if(x.ok===true)return x}catch{}}Atomics.wait(new Int32Array(new SharedArrayBuffer(4)),0,0,200)}fail('loop_health_not_ready:'+port)}
function atomicReplace(file,content,mode){const tmp=file+'.v8-'+process.pid+'.tmp';fs.writeFileSync(tmp,content,{mode});fs.chmodSync(tmp,mode);fs.renameSync(tmp,file)}
function candidate(){const original={base:fs.readFileSync(FILES.base,'utf8'),executor:fs.readFileSync(FILES.executor,'utf8'),plugin:fs.readFileSync(FILES.plugin,'utf8'),policy:fs.readFileSync(FILES.policy,'utf8'),v4helper:fs.readFileSync(FILES.v4helper,'utf8')};const c={base:patchBase(original.base),executor:patchExecutor(original.executor),plugin:patchPlugin(original.plugin),policy:patchPolicy(original.policy),v4helper:null,helper:Buffer.from(HELPER_B64,'base64')};const pluginSha=shaBuf(Buffer.from(c.plugin));c.v4helper=patchV4Helper(original.v4helper,pluginSha);return {original,c,pluginSha}}
function validateCandidate(c){syntax('base',c.base);syntax('executor',c.executor);syntax('plugin',c.plugin,true);JSON.parse(c.policy);syntax('v4helper',c.v4helper);syntax('helper',c.helper.toString('utf8'));if(shaBuf(c.helper)!==HELPER_SHA)fail('helper_sha_candidate_mismatch')}
function helperPreflight(c){const tmp='/tmp/prhm-v8-helper-'+process.pid+'.js';try{fs.writeFileSync(tmp,c.helper,{mode:0o700});const r=exec('/usr/local/bin/prhm-node',[tmp,'--preflight-only'],{timeout:90000});const x=JSON.parse(String(r.stdout||'').trim());if(x.ok!==true||x.preflight_only!==true||x.action!==ACTION||x.production_mutation!==false||x.p0_live!==false||x.proposal_send!==false||x.bid_send!==false)fail('helper_preflight_invalid');return x}finally{try{fs.unlinkSync(tmp)}catch{}}}
function restartAndHealth(){exec('/usr/bin/systemctl',['restart','prhm-agent-selfmaint.service']);exec('/usr/bin/systemctl',['restart','prhm-agent-selfmaint-exec.service']);exec('/usr/bin/systemctl',['restart','prhm-agent-mcp.service']);const base=unixHealth('/run/prhm-agent-selfmaint/selfmaint.sock');const self=unixHealth('/run/prhm-agent-selfmaint-exec/exec.sock',VERSION);const mcp=loopHealth(8123);return {base,self,mcp}}
function main(){const args=process.argv.slice(2);if(args.length>1||(args.length===1&&args[0]!=='--preflight-only'))fail('unexpected_arguments');if(process.getuid&&process.getuid()!==0)fail('must_run_as_root');baseline();const {original,c,pluginSha}=candidate();validateCandidate(c);const hp=helperPreflight(c);const report={ok:true,schema_version:'prhm.host-action-bootstrap-preflight.v1',preflight_only:args[0]==='--preflight-only',action:ACTION,current_hashes:EXPECTED,candidate_hashes:{base:shaBuf(Buffer.from(c.base)),executor:shaBuf(Buffer.from(c.executor)),plugin:pluginSha,policy:shaBuf(Buffer.from(c.policy)),v4helper:shaBuf(Buffer.from(c.v4helper)),helper:HELPER_SHA},target_version:VERSION,helper_preflight:hp,uat_executed:false,database_mutation:false,business_mutation:false,p0_live:false,proposal_send:false,bid_send:false,production_mutation:false};if(args[0]==='--preflight-only'){process.stdout.write(JSON.stringify(report)+String.fromCharCode(10));return}const stamp=new Date().toISOString().replace(/[-:.TZ]/g,'').slice(0,14),backupDir='/var/backups/prhm-host-actions-v8-verified-economics-replay-'+stamp;fs.mkdirSync(backupDir,{recursive:true,mode:0o700});const modes={base:0o755,executor:0o755,plugin:0o644,policy:0o644,v4helper:0o755};for(const k of ['base','executor','plugin','policy','v4helper']){const dst=path.join(backupDir,k+'-'+path.basename(FILES[k])+'.bak');fs.copyFileSync(FILES[k],dst,fs.constants.COPYFILE_EXCL);fs.chmodSync(dst,0o600)}let ok=false;try{atomicReplace(FILES.helper,c.helper,0o755);for(const k of ['base','executor','plugin','policy','v4helper'])atomicReplace(FILES[k],c[k],modes[k]);for(const k of ['base','executor','plugin','policy','v4helper']){const want=report.candidate_hashes[k],got=sha(FILES[k]);if(got!==want)fail('post_sha_mismatch:'+k+':'+got+':'+want)}if(sha(FILES.helper)!==HELPER_SHA)fail('helper_post_sha_mismatch');const health=restartAndHealth();const p=JSON.parse(fs.readFileSync(FILES.policy,'utf8'));if(p.operations?.['host_action.real_market_verified_economics_uat_v1']?.level!==4)fail('policy_operation_postverify_failed');if(!p.typed_scopes.some(x=>x&&x.action===ACTION&&x.operation==='host_action.real_market_verified_economics_uat_v1'&&x.risk==='critical'))fail('policy_scope_postverify_failed');if(!fs.readFileSync(FILES.plugin,'utf8').includes('real_market_verified_economics_uat_v1'))fail('plugin_enum_postverify_failed');if(!fs.readFileSync(FILES.v4helper,'utf8').includes(pluginSha))fail('v4_plugin_sha_postverify_failed');ok=true;process.stdout.write(JSON.stringify({ok:true,schema_version:'prhm.host-action-install-result.v1',installed:true,version:VERSION,action:ACTION,helper_sha256:HELPER_SHA,mcp_plugin_sha256:pluginSha,approval_policy_version:p.version,health,uat_executed:false,database_mutation:false,business_mutation:false,p0_live:false,proposal_send:false,bid_send:false,backup_dir:backupDir})+String.fromCharCode(10))}finally{if(!ok){try{for(const k of ['base','executor','plugin','policy','v4helper']){const src=path.join(backupDir,k+'-'+path.basename(FILES[k])+'.bak');if(fs.existsSync(src)){const mode=modes[k];atomicReplace(FILES[k],fs.readFileSync(src),mode)}}try{fs.unlinkSync(FILES.helper)}catch(e){if(e.code!=='ENOENT')throw e}restartAndHealth()}catch(rb){process.stderr.write('rollback_failed:'+String(rb&&rb.stack||rb)+String.fromCharCode(10))}}}}
try{main()}catch(e){process.stderr.write(String(e&&e.stack||e)+String.fromCharCode(10));process.exit(1)}
